package com.oms.order.service;

import org.junit.jupiter.api.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.test.util.ReflectionTestUtils;
import com.ruoyi.common.core.domain.R;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.GiftRules.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class GiftServiceTest {
    RefundServiceTest f;GiftService gifts;RefundGoodsService goods;long plan,giftLine,paidLine;
    @BeforeAll static void start(){RefundServiceTest.start();}
    @BeforeEach void setup(){f=new RefundServiceTest();f.reset();for(String t:Arrays.asList("oms_gift_resolution","oms_gift_event","oms_gift_plan","oms_gift_group_version","oms_gift_group"))f.db.update("DELETE FROM "+t);
        gifts=new GiftService();gifts.repository=f.repo;gifts.catalog=mock(OrderCatalog.class);gifts.inventory=mock(OrderWarehouseClient.class);gifts.cutoffs=mock(OrderCutoffService.class);ObjectProvider<GiftService> provider=mock(ObjectProvider.class);when(provider.getIfAvailable()).thenReturn(gifts);ReflectionTestUtils.setField(f.repo,"giftProvider",provider);
        paidLine=f.db.queryForObject("SELECT id FROM oms_order_line",Long.class);
        Map<String,Object> group=GiftRulesTest.group(1,Collections.singletonList(GiftRulesTest.rule("R1","MULTIPLE",2,"0","G")));List<Map<String,Object>> basis=Collections.singletonList(map("platform_oid","987654321012345679","sku_sn","A","quantity",5,"payment","25"));Map<String,Object> snapshot=evaluate(Collections.singletonList(group),1,"2026-10-19 00:00:00",basis);
        plan=f.repo.insert("INSERT INTO oms_gift_plan(company_code,platform_order_id,order_id,channel_id,snapshot,basis_json,initial_json) VALUES ('VERIFY',?,?,1,?,?,?)",f.platform,f.order,encode(snapshot),encode(basis),encode(snapshot.get("gifts")));
        giftLine=f.repo.insert("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,reserved_quantity,gift_plan_id) VALUES ('VERIFY',?,'','G','赠品',2,0,2,?)",f.order,plan);gifts.bind("VERIFY",f.platform,f.order);
        goods=new RefundGoodsService();goods.refunds=f.refunds;goods.inventory=gifts.inventory;goods.catalog=gifts.catalog;goods.returns=mock(RefundReturnClient.class);
        when(gifts.inventory.returnBasis(anyString(),anyMap(),anyString())).thenReturn(R.ok(map("quantity",2,"unit_cost","1.00")));when(gifts.catalog.warehouses("VERIFY")).thenReturn(Collections.singletonList(map("wms_simulation_code","V","wms_simulation_name","退回仓")));
    }
    @AfterEach void finish(){f.clear();for(String t:Arrays.asList("oms_gift_resolution","oms_gift_event","oms_gift_plan","oms_gift_group_version","oms_gift_group"))f.db.update("DELETE FROM "+t);}
    long refund(String rid,int quantity,String status,boolean review){Map<String,Object> source=f.source(1,"10.00",status),payload=RefundValues.parse(text(source,"jdp_response"));source.put("refund_id",rid);payload.put("refund_id",rid);payload.put("num",quantity);source.put("jdp_response",encode(map("refund_get_response",map("refund",payload))));long id=f.convert(f.ingest(source));if(review){Map<String,Object> body=f.review(id,"CANCEL","CANCEL");body.put("cancel_line_id",paidLine);body.put("cancel_quantity",quantity);f.workspace.review("VERIFY",id,body,"test");}return id;}
    Map<String,Object> report(){return gifts.report("VERIFY",f.order);}
    Map<String,Object> line(){return rows(report().get("lines")).get(0);}
    Map<String,Object> command(){Map<String,Object> r=report();return map("control_version",r.get("control_version"),"order_line_id",giftLine);}
    long shipGift(long qty){long sh=f.repo.insert("INSERT INTO oms_order_shipment(company_code,shipment_sn,order_id,order_sn,channel_id,platform_tid,generation_no,owner_code,real_store_code,real_store_name,quantity,status,created_by) VALUES ('VERIFY','XS_GIFT',?,'SO_REFUND',1,'987654321012345678',1,'O','R','R',2,'PART_SHIPPED','test')",f.order);return f.repo.insert("INSERT INTO oms_order_shipment_line(company_code,shipment_id,order_line_id,platform_oid,sku_sn,goods_name,quantity,shipped_quantity,allocation_id,stock_source_id,store_code,batch_id,source_type) VALUES ('VERIFY',?,?,'','G','赠品',2,?,12,12,'V',1,'PUBLIC_EXTRA')",sh,giftLine,qty);}
    @Test void untouchedGiftsRemainEligibleAndReadIsStable(){assertEquals(2,number(line(),"eligible_quantity"));long version=number(report(),"control_version");assertEquals(version,number(report(),"control_version"));assertEquals("",report().get("block_reason"));verifyNoInteractions(gifts.inventory);}
    @Test void pendingRefundOnlyHoldsAndDoesNotCancelOrRequestReturn(){refund("90001",2,"WAIT_SELLER_AGREE",true);Map<String,Object> l=line();assertEquals(2,number(l,"eligible_quantity"));assertEquals(1,number(l,"projected_eligible_quantity"));assertEquals(0,number(l,"cancel_required"));assertEquals(0,number(l,"return_required"));assertEquals("PENDING_REVIEW",l.get("gift_state"));verifyNoInteractions(gifts.inventory);}
    @Test void withdrawnRefundRestoresPendingEligibilityWithoutNewGift(){long id=refund("90001",2,"WAIT_SELLER_AGREE",true);Map<String,Object> source=f.source(2,"10.00","CLOSED"),payload=RefundValues.parse(text(source,"jdp_response"));source.put("refund_id","90001");payload.put("refund_id","90001");payload.put("num",2);source.put("jdp_response",encode(map("refund_get_response",map("refund",payload))));f.ingest(source);assertEquals("ELIGIBLE",line().get("gift_state"));assertEquals(2,f.db.queryForObject("SELECT quantity FROM oms_order_line WHERE id=?",Integer.class,giftLine));}
    @Test void confirmedPartialRefundCancelsOnlyExcessUnshippedGift(){refund("90001",2,"SUCCESS",true);assertEquals(1,number(line(),"cancel_required"));assertEquals(0,number(line(),"return_required"));}
    @Test void oneShippedOneUnshippedAndOneRetainedDoesNotDoubleRecover(){shipGift(1);refund("90001",2,"SUCCESS",true);assertEquals(1,number(line(),"cancel_required"));assertEquals(0,number(line(),"return_required"));}
    @Test void twoShippedAndOneRetainedRequiresOnlyOneReturn(){shipGift(2);refund("90001",2,"SUCCESS",true);assertEquals(0,number(line(),"cancel_required"));assertEquals(1,number(line(),"return_required"));}
    @Test void cumulativeRefundsDoNotDuplicateGiftRecovery(){shipGift(2);refund("90001",1,"SUCCESS",true);refund("90002",1,"SUCCESS",true);assertEquals(1,number(line(),"return_required"));assertEquals(1,number(line(),"unarranged_quantity"));}
    @Test void compensationKeepDoesNotInvalidateGifts(){long id=refund("90001",1,"SUCCESS",false);f.workspace.review("VERIFY",id,f.review(id,"COMPENSATION","KEEP"),"test");assertEquals("ELIGIBLE",line().get("gift_state"));assertEquals(2,number(line(),"eligible_quantity"));}
    @Test void priceDifferenceOnlyAffectsThresholdWhenOriginalPolicyEnabled(){long id=refund("90001",1,"SUCCESS",false);f.workspace.review("VERIFY",id,f.review(id,"DIFFERENCE","KEEP"),"test");assertEquals("ELIGIBLE",line().get("gift_state"));}
    @Test void waiverRequiresPermissionPolicyEvidenceAndNeverIncreasesStock(){shipGift(2);refund("90001",2,"SUCCESS",true);Map<String,Object> body=command();body.putAll(map("quantity",1,"confirmed",true,"reason","批准客户保留","evidence","客服审批001"));gifts.waive("VERIFY",f.order,body,"test");assertEquals(0,number(line(),"return_required"));assertEquals(1,number(line(),"waived_quantity"));assertEquals(0,number(line(),"returned_quantity"));verifyNoInteractions(gifts.inventory);}
    @Test void waiverCannotResolveUnshippedCancellation(){refund("90001",2,"SUCCESS",true);Map<String,Object> body=command();body.putAll(map("quantity",1,"confirmed",true,"reason","test","evidence","test"));assertThrows(IllegalArgumentException.class,()->gifts.waive("VERIFY",f.order,body,"test"));}
    @Test void stockTimeoutReusesFrozenReductionAndDoesNotChangeLocalBalance(){refund("90001",2,"SUCCESS",true);when(gifts.inventory.adjust(anyString(),anyMap(),anyString())).thenThrow(new IllegalArgumentException("timeout"));assertThrows(IllegalArgumentException.class,()->gifts.cancel("VERIFY",f.order,command(),"test"));String request=f.db.queryForObject("SELECT command_json FROM oms_gift_resolution",String.class);assertEquals(0,f.db.queryForObject("SELECT cancelled_quantity FROM oms_order_line WHERE id=?",Integer.class,giftLine));doAnswer(call->{assertEquals(object(request),call.getArgument(1));return R.ok(map("state","COMPLETED","lines",Collections.singletonList(map("platform_oid","","sku_sn","G","cancelled_quantity",1,"reserved_quantity",1))));}).when(gifts.inventory).adjust(anyString(),anyMap(),anyString());gifts.cancel("VERIFY",f.order,command(),"test");assertEquals(1,f.db.queryForObject("SELECT COUNT(*) FROM oms_gift_resolution",Integer.class));assertEquals(1,number(line(),"cancelled_quantity"));}
    @Test void allocatedGiftRequiresWarehouseWithdrawalBeforeStockReduction(){shipGift(0);refund("90001",2,"SUCCESS",true);Map<String,Object> out=gifts.cancel("VERIFY",f.order,command(),"test");assertEquals("WAIT_CUTOFF",out.get("state"));verify(gifts.cutoffs).request(eq("VERIFY"),eq(f.order),argThat(m->"REPLAN".equals(text(m,"mode"))),eq("test"));verifyNoInteractions(gifts.inventory);}
    @Test void giftReturnUsesActualOutboundSourceAndOriginalTkWithoutChangingFunds(){long source=shipGift(2),refund=refund("90001",2,"SUCCESS",true);Map<String,Object> b=f.refunds.business("VERIFY",refund,false);Map<String,Object> input=map("control_version",b.get("control_version"),"gift_plan_id",plan,"shipment_line_id",source,"quantity",1,"confirmed",true,"request_key","GIFT_TEST_0001","store_code","V","return_address","验收地址","return_contact","验收联系人","reason","赠品失去资格","evidence","TEST-GIFT");long id=number(goods.create("VERIFY",refund,input,"test"),"id");assertEquals(plan,f.db.queryForObject("SELECT gift_plan_id FROM oms_refund_return_plan WHERE id=?",Long.class,id));assertEquals(0,number(line(),"unarranged_quantity"));assertEquals(1,number(line(),"return_required"));assertEquals("SUCCESS",f.refunds.business("VERIFY",refund,false).get("funds_state"));verify(gifts.inventory).returnBasis(eq("VERIFY"),argThat(m->text(m,"platform_oid").isEmpty()&&"G".equals(text(m,"sku_sn"))),anyString());verifyNoInteractions(goods.returns);}
    @Test void cannotArrangeMoreThanGiftEntitlementOrUseAnotherCompany(){long source=shipGift(2),refund=refund("90001",2,"SUCCESS",true);Map<String,Object> b=f.refunds.business("VERIFY",refund,false);Map<String,Object> body=map("control_version",b.get("control_version"),"gift_plan_id",plan,"shipment_line_id",source,"quantity",2,"confirmed",true,"request_key","GIFT_TEST_0001","store_code","V","return_address","验收地址","return_contact","验收联系人","reason","test","evidence","test");assertThrows(IllegalArgumentException.class,()->goods.create("VERIFY",refund,body,"test"));assertThrows(IllegalArgumentException.class,()->gifts.report("OTHER",f.order));}
    long returnPlan(long source,long refund){return number(goods.create("VERIFY",refund,map("control_version",f.refunds.business("VERIFY",refund,false).get("control_version"),"gift_plan_id",plan,"shipment_line_id",source,"quantity",1,"confirmed",true,"request_key","GIFT_TEST_0001","store_code","V","return_address","验收地址","return_contact","验收联系人","reason","test","evidence","test"),"test"),"id");}
    Map<String,Object> planBody(long refund,long p){return map("control_version",f.refunds.business("VERIFY",refund,false).get("control_version"),"plan_version",f.db.queryForObject("SELECT control_version FROM oms_refund_return_plan WHERE id=?",Long.class,p),"quantity",1,"confirmed",true,"reason","审批确认不再追回","evidence","TEST-WAIVER");}
    void forbidWaiver(){Map<String,Object> snapshot=object(f.db.queryForObject("SELECT snapshot FROM oms_gift_plan WHERE id=?",String.class,plan));List<Map<String,Object>> entitlements=rows(snapshot.get("entitlements"));Map<String,Object> p=object(entitlements.get(0).get("policy"));p.put("allow_waive",false);entitlements.get(0).put("policy",p);snapshot.put("entitlements",entitlements);f.db.update("UPDATE oms_gift_plan SET snapshot=? WHERE id=?",encode(snapshot),plan);}
    @Test void waiverOnStoppedReturnPlanCountsOnceAndDoesNotBecomeAnotherReturnDemand(){long source=shipGift(2),refund=refund("90001",2,"SUCCESS",true),p=returnPlan(source,refund);goods.action("VERIFY",refund,p,0,"cancel",planBody(refund,p),"test");goods.action("VERIFY",refund,p,0,"waive",planBody(refund,p),"test");assertEquals(1,number(line(),"waived_quantity"));assertEquals(0,number(line(),"unarranged_quantity"));assertEquals(0,number(line(),"return_required"));assertEquals(0,number(line(),"returned_quantity"));verifyNoInteractions(goods.returns);}
    @Test void originalNoWaiverPolicyAlsoAppliesThroughReturnDocumentActions(){long source=shipGift(2),refund=refund("90001",2,"SUCCESS",true),p=returnPlan(source,refund);goods.action("VERIFY",refund,p,0,"cancel",planBody(refund,p),"test");forbidWaiver();assertThrows(IllegalArgumentException.class,()->goods.action("VERIFY",refund,p,0,"waive",planBody(refund,p),"test"));assertEquals(0,number(line(),"waived_quantity"));assertEquals(1,number(line(),"return_required"));}
}
